import json, pathlib, html
root=pathlib.Path.cwd(); out=root/'audit-results/inspection-2026-10-15'; data=json.loads((out/'inspection.json').read_text()); issues=[]
def add(id,priority,pages,title,observation,suggestion,steps,evidence,kind='Confirmed issue'):
 issues.append(dict(id=id,priority=priority,pages=pages,title=title,observation=observation,suggestion=suggestion,steps=steps,evidence=evidence,kind=kind))
allpages=[p['name'] for p in data['pages']]
add('UI-01','P1',['book-a-visit','apply-online','contact'],'Submission succeeds visually without sending data','Each populated form shows a success toast, clears the entered name, and produces zero network requests during submission. The shared JavaScript only prevents default submission, shows a toast and resets the form.','Connect each form to a working submission endpoint; show success only after a confirmed response. Preserve entries on error, provide retry feedback and a request reference.','Fill a form and submit while watching Network; observe success, cleared values and no submission request.','main.js:393; book-a-visit-submission.png; apply-online-submission.png; contact-submission.png')
add('UI-02','P1',['book-a-visit','apply-online','contact'],'Required fields are not enforced','All three forms use novalidate; their submit handlers do not call checkValidity or reportValidity. Empty submissions therefore reach the same success handler.','Enable native validation or add accessible field validation and an error summary. Prevent submission until required fields and formats pass.','Load a fresh form and press its submit button without entering anything.','main.js:393; book-a-visit.html:309; apply-online.html:290; contact.html:345')
add('UI-03','P2',['index','programs','admissions','apply-online'],'Age eligibility contradicts itself','Home and Programs say 6 months–4 years, infant cards say 3–11 months, and Admissions/Application say 6 months–6 years. This directly affects program selection.','Confirm the actual campus/program eligibility and use one consistent age table throughout the site and application. Explain any campus differences.','Compare Home age cards, Programs age section, Admissions introduction and Application introduction.','index.html:542; programs.html:416; admissions.html:268; apply-online.html:268')
add('UI-04','P2',['parents'],'App Store and Google Play buttons have the same website destination','The web login, iOS download and Android download links all point to https://shomoukh.com/parents/. The two store buttons do not directly link to their advertised stores.','Use verified store listing URLs and a verified login URL; if downloads require an intermediary, label that step explicitly.','Inspect the three platform button destinations on Parents.','parents.html:300; parents.html:313; parents.html:326')
add('UI-05','P2',['index','spaces','admissions','book-a-visit','apply-online','parents','contact'],'Privacy and terms links open About','The footer Privacy Policy and Terms of Service links point to /about.html, which contains school information rather than those documents.','Publish dedicated privacy and terms content and link it consistently, including beside forms that collect family and health details.','Follow either footer policy link and inspect the destination.','apply-online.html:595; contact.html:556; index.html:1027')
add('UI-06','P2',allpages,'Social icons link to generic platform homepages','Facebook, Instagram, YouTube and LinkedIn links use the platform root URLs rather than school profiles.','Replace them with confirmed school profile URLs; remove any channel with no active profile.','Inspect the social icon hrefs in the menu/footer.','about.html:242; parents.html:242')
add('UI-07','P2',allpages,'Drawer does not move keyboard focus into the open dialog','After clicking Menu, activeElement remains menu-toggle-btn outside the drawer. The opening code sets visibility and scroll lock without focus management. Closing also lacks focus restoration.','Move focus to the close button or first navigation item, contain Tab within the drawer, make background content inert and restore focus when closing.','Focus Menu, open it, then use Tab/Shift+Tab; check the active element against the open dialog.','main.js:31; index-mobile-menu.png')
add('UI-08','P2',allpages,'Dialogs lack consistent keyboard focus containment','Search moves focus to its input but does not trap it or restore the opener. Enrichment detail dialogs leave focus on their underlying cards; shared handlers do not make the background inert.','Use a shared accessible dialog controller with initial focus, focus containment, Escape handling and focus return.','Open Search or an enrichment detail, then navigate using Tab and Shift+Tab.','main.js:101; main.js:336; enrichments-detail-modal.png')
add('UI-09','P2',allpages,'Unknown search terms silently open About','Submitting zzzauditnomatch redirects to /about.html. Search uses substring routing without results or a no-match message.','Provide matching results and an explicit no-results state that retains the query. Use topic shortcuts as clearly labelled shortcuts.','Search for zzzauditnomatch.','main.js:132; inspection.json')
add('UI-10','P2',['index'],'Arabic language selection has no translation behavior','The hero has English/Arabic options, but the shared script has no change handler or language routing for the selector.','Connect it to a complete Arabic version with RTL layout and translated navigation/content; otherwise remove the unsupported choice.','Select العربية in the hero selector and compare the page language and layout.','index.html:339; main.js')
add('UI-11','P2',['book-a-visit'],'Introductory paragraph is hard to read on its dark card','The guidance paragraph renders dark grey (#595D62) on dark teal (#1C3A47), approximately 1.81:1 contrast, visibly reducing legibility on desktop and mobile.','Use a light text token on the dark surface and verify contrast in normal, hover and focus states.','Read the paragraph immediately under the Campus Experience heading.','book-a-visit.html:285; book-a-visit-mobile-frame.png; book-a-visit-desktop-full.png')
add('UI-12','P2',allpages,'Coral/white text combinations need stronger contrast','Coral text on white and white text on coral appear in labels, links and primary buttons. The base coral #F28F79 versus white is approximately 2.34:1.','Use a darker coral text/button token or dark teal foreground; check each final rendered state rather than changing the decorative palette globally.','Inspect coral action labels and white text on coral CTAs at normal zoom.','style.css:9; enrichments-desktop-full.png; book-a-visit-desktop-full.png')
add('UI-13','P2',['book-a-visit','apply-online'],'Date controls have no meaningful bounds','Child birth-date inputs and the tour datetime control have no min/max attributes. The UI allows future birth dates and past visit dates.','Bound birth dates and tour dates, explain the visit timezone and available hours, and validate age against the chosen program. Repeat validation at the endpoint.','Open the date controls and choose a future birth date or past visit date.','book-a-visit.html:357; apply-online.html:338; inspection.json')
add('UI-14','P2',['apply-online'],'Required documents are pre-checked without upload or delivery instructions','The four document boxes are already selected. There is no file upload and no clear next step for supplying the actual documents; Admissions says documentation is submitted with the application.','Start readiness boxes unchecked and distinguish preparation from delivery. Add secure uploads or an explicit later delivery step and document status.','Inspect the Required Documents section and compare Admissions Step 2.','apply-online.html:428; admissions.html:340; apply-online-desktop-full.png')
add('UI-15','P3',['apply-online'],'Expired seasonal application option remains selectable','Summer Camp 2026 is offered alongside 2026–2027 even though this inspection is on 15 October 2026.','Confirm whether this is intentional; remove closed sessions or clearly label archived registrations and expose the next available session.','Open Academic Year Selection.','apply-online.html:298')
add('UI-16','P3',['apply-online'],'Long application has no progress, save or review step','The form requests enrollment, child, guardian, health and document information in one long page. A reset or navigation away loses entries.','Group the form into clear steps with progress, a review summary and a considered draft-saving flow for sensitive details. Preserve entries after failed submission.','Complete the first sections, navigate away and return.','apply-online-desktop-full.png; apply-online-mobile-full.png', 'UX recommendation')
add('UI-17','P3',['contact'],'General inquiries unnecessarily require child information','The general Contact form requires a child birth date and limits messages to 180 characters. Visitors asking about fees, jobs or visits may not have that information or enough space.','Ask for inquiry type; make child data conditional and allow a longer message with helpful validation.','Inspect required fields and the message character limit.','contact.html:345; contact-desktop-full.png','UX recommendation')
add('UI-18','P3',['contact'],'Campus addresses offer no directions action','Campus cards provide text addresses, phone and email links but no map or directions link.','Add verified Open in Maps / Get Directions links for each campus, with location context and accessible labels.','Inspect both campus contact cards.','contact-desktop-full.png; contact.html:293','UX recommendation')
add('UI-19','P3',['about','programs','enrichments'],'Large desktop section gaps slow scanning','The desktop pages have substantial blank bands between content groups, especially before the philosophy/pillars and enrichment activity sections.','Reduce repeated vertical padding and use a consistent spacing scale. Keep separation where it communicates a new topic.','Scroll the desktop full-page captures and compare spacing between consecutive sections.','about-desktop-full.png; programs-desktop-full.png; enrichments-desktop-full.png','Visual recommendation')
add('UI-20','P3',['spaces'],'Facility list is difficult to preview visually','Fourteen spaces are primarily presented as icon/text cards and repeated textual highlights, with only one introductory photo.','Add representative photographs or a small accessible gallery, labelled by campus, so families can preview facilities before booking.','Review the facilities grid and signature spaces.','spaces-desktop-full.png','Visual recommendation')
add('UI-21','P3',['admissions'],'Secure Your Place ends without an actionable next step','Step 3 tells families to pay within a given time frame but supplies no actual deadline, fee guidance or link to ask about payment.','Explain when the deadline is issued and how payment instructions arrive; add an admissions contact action and link to published fee information if available.','Read the third enrollment step after following Steps 1 and 2.','admissions.html:349; admissions-desktop-full.png','UX recommendation')
add('UI-22','P3',['book-a-visit','parents','contact'],'Primary mobile task is pushed below introductory content','At 390×844, booking shows guidance before the form, Parents shows introduction before platform actions, and Contact shows campus details before the message form.','Add an early jump CTA to Book Your Visit, Sign In/Download or Send a Message, and reduce repeated introductory copy on mobile.','Open each page on mobile and locate the first task action.','book-a-visit-mobile-frame.png; parents-mobile-frame.png; contact-mobile-frame.png','UX recommendation')
add('UI-23','P2',allpages,'Closed navigation drawer remains in keyboard tab order','On every page, pressing Tab after focusing the Menu button moves focus to an anchor inside the closed aria-hidden drawer. Keyboard users can land on invisible controls.','Use inert or equivalent focus suppression while the drawer is closed; restore tabbability only when it opens.','Close the menu, focus its trigger and press Tab once.','interactions.json; main.js:31')
add('UI-24','P3',['index'],'Video button accessible label does not match its state','After pausing the hero video, the visible button says PLAY VIDEO while its aria-label still says Pause background video.','Update the accessible name with the visible action or use a consistently named toggle with aria-pressed.','Click Pause Video and inspect the accessible button name.','interactions.json; main.js:205')
(out/'issues.json').write_text(json.dumps(issues,indent=2))
labels={'index':'Home','about':'About','programs':'Programs','enrichments':'Enrichments','spaces':'Spaces','admissions':'Admissions','book-a-visit':'Book a Visit','apply-online':'Apply Online','parents':'Parents','contact':'Contact'}
intro='Inspected the current local source site on 15 October 2026 (Asia/Muscat), using Chrome at 1440×900, 768×1024, 390×844 and 320×740. Captures include each page’s initial frame and full scrollable content. This is an inspection report; no product fixes were applied. P1 = blocks a core task; P2 = significant usability/behavior issue; P3 = improvement. Recommendations are distinguished from confirmed defects.'
md=['# UI inspection report — 15 October 2026',intro,'## Findings',f'{len(issues)} findings: '+', '.join(f'{sum(x["priority"]==k for x in issues)} {k}' for k in ['P1','P2','P3'])+'. The submission handlers are the first repair priority.','## Page-by-page inspection']
for p in data['pages']:
 n=p['name']; relevant=[i for i in issues if n in i['pages']];md += [f'### {labels[n]}',f'[Open page]({data["base"]}{p["path"]}) · [Desktop frame](audit-results/inspection-2026-10-15/{n}-desktop-frame.png) · [Desktop full page](audit-results/inspection-2026-10-15/{n}-desktop-full.png) · [Mobile frame](audit-results/inspection-2026-10-15/{n}-mobile-frame.png) · [Mobile full page](audit-results/inspection-2026-10-15/{n}-mobile-full.png)', 'Issues: '+', '.join(f'[{i["id"]}](#{i["id"].lower()})' for i in relevant)+'.']
md+=['## Detailed issue register']
for i in issues:md += [f'### {i["id"]}',f'**{i["priority"]} — {i["title"]}** ({i["kind"]})',f'Pages: '+', '.join(labels[n] for n in i['pages']),f'Observed: {i["observation"]}',f'Suggestion: {i["suggestion"]}',f'Reproduce: {i["steps"]}',f'Evidence: {i["evidence"]}']
md+=['## Submission links',*[f'- [{labels[n]} form]({data["base"]}/{n}.html#{id})' for n,id in [('book-a-visit','tour-booking-form'),('apply-online','online-enrollment-form'),('contact','contact-inquiry-form')]],'## Checks and limits','All 40 page/viewport combinations loaded with no detected horizontal document overflow or broken page images. Local fragment destinations were checked against page IDs. Menu/search opening and Escape closure were exercised on each page. Shared navigation has accordion sections, not a separate ARIA tab interface. All 70 navigation accordion sections and all 16 enrichment cards across Home and Enrichments were opened. Empty submissions, language selection and hero video pause were exercised. Additional interaction evidence is saved in interactions.json.','Browser emulation is not physical iOS/Android testing. External social profiles, app stores and authenticated parent services were inspected as link destinations, not signed into. This report does not claim a complete accessibility conformance audit. The development server links work while the local server is running; screenshot links are permanent workspace artifacts. No external submission system was requested after clarification.']
(root/'UI_INSPECTION_REPORT_2026-10-15.md').write_text('\n\n'.join(md)+'\n')
esc=html.escape
css='body{font:16px/1.6 system-ui;color:#173843;background:#f6f4ef;margin:0}main{max-width:1160px;margin:auto;padding:32px}h1{font-size:40px}h2{margin-top:40px}a{color:#006678}article,section{background:white;padding:24px;margin:24px 0;border-radius:16px;border:1px solid #dbe1df}.frames{display:grid;grid-template-columns:3fr 1fr;gap:20px}.frames img{width:100%;border:1px solid #dde4e4}.badge{background:#ffebdb;padding:4px 10px;border-radius:20px}nav a{margin-right:14px}details{margin:12px 0}summary{cursor:pointer}p{max-width:100ch}@media(max-width:650px){.frames{grid-template-columns:1fr}main{padding:16px}}'
parts=[f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Shomoukh UI inspection</title><style>{css}</style><main><h1>Shomoukh UI inspection</h1><p>15 October 2026 · 10 pages · 4 screen sizes · {len(issues)} findings</p><p>{esc(intro)}</p><p><strong>First priority:</strong> all three forms report success without delivering data.</p><nav>'+''.join(f'<a href="#{n}">{labels[n]}</a>' for n in allpages)+'</nav>']
for p in data['pages']:
 n=p['name'];parts += [f'<section id="{n}"><h2>{labels[n]}</h2><p><a href="{data["base"]}{p["path"]}">Open inspected page</a></p><div class="frames"><a href="{n}-desktop-full.png"><img loading="lazy" src="{n}-desktop-frame.png" alt="{labels[n]} desktop capture"></a><a href="{n}-mobile-full.png"><img loading="lazy" src="{n}-mobile-frame.png" alt="{labels[n]} mobile capture"></a></div><p>'+ ' · '.join(f'<a href="{n}-{vp}-{s}.png">{vp} {s}</a>' for vp in ['desktop','tablet','mobile','small-mobile'] for s in ['frame','full'])+'</p>']
 for i in issues:
  if n in i['pages']:parts.append(f'<details><summary><span class="badge">{i["priority"]}</span> <a href="#{i["id"]}">{i["id"]}</a> {esc(i["title"])}</summary><p>{esc(i["observation"])}</p><p><strong>Suggestion:</strong> {esc(i["suggestion"])}</p></details>')
 parts.append('<p>Interaction frames: '+ ' · '.join(f'<a href="{n}-{state}.png">{state}</a>' for state in ['mobile-menu','mobile-search'])+'</p>');
 if n in ['index','enrichments']:parts.append('<p>All detail cards: '+ ' · '.join(f'<a href="{n}-detail-{j}.png">Card {j}</a>' for j in range(1,9))+'</p>')
 parts.append('</section>')
parts.append('<h2>Issue register</h2>')
for i in issues:
 evidence=[]
 for e in i['evidence'].split('; '):
  if e.endswith('.png'):evidence.append(f'<a href="{esc(e)}">{esc(e)}</a>')
  elif ':' in e:
   file,line=e.split(':',1);evidence.append(f'<a href="../../{esc(file)}">{esc(file)} line {esc(line)}</a>')
  else:evidence.append(esc(e))
 parts.append(f'<article id="{i["id"]}"><span class="badge">{i["priority"]} · {esc(i["kind"])}</span><h2>{i["id"]} — {esc(i["title"])}</h2><p>Pages: '+', '.join(f'<a href="#{n}">{labels[n]}</a>' for n in i['pages'])+f'</p><p><strong>Observed:</strong> {esc(i["observation"])}</p><p><strong>Suggestion:</strong> {esc(i["suggestion"])}</p><p><strong>Reproduce:</strong> {esc(i["steps"])}</p><p>Evidence: '+ ' · '.join(evidence)+'</p></article>')
parts.append('<section><h2>Submission forms</h2>'+''.join(f'<p><a href="{data["base"]}/{n}.html#{id}">{labels[n]} form</a> · <a href="{n}-submission.png">Submission capture</a> · <a href="{n}-empty-submit.png">Empty submission capture</a></p>' for n,id in [('book-a-visit','tour-booking-form'),('apply-online','online-enrollment-form'),('contact','contact-inquiry-form')])+'<h2>Verification and limits</h2><p>No horizontal document overflow or broken page images detected across 40 combinations. Local fragment links resolve to existing IDs. See <a href="inspection.json">page evidence</a>, <a href="interactions.json">interaction evidence</a> and <a href="issues.json">issue data</a>.</p><p>Chrome emulation; no physical device or authenticated external service inspection. Confirmed defects and design recommendations are distinguished. Local page links require the development server. No external report submission was requested after clarification.</p></section></main></html>')
(out/'report.html').write_text(''.join(parts));print('Wrote report with',len(issues),'findings')
